        <div class="toolbar"><el-button :disabled="!canEdit" @click="move(-1)">上移内容组件</el-button><el-button :disabled="!canEdit" @click="move(1)">下移内容组件</el-button><el-button :disabled="!canEdit" @click="add(true)">复制内容组件</el-button><el-button type="danger" :disabled="!canEdit" @click="remove">删除当前内容组件</el-button></div>
        <template v-if="block && kind">
          <el-form label-position="top" :disabled="!canEdit">
            <el-form-item label="内容组件显示"><el-select :model-value="!flag(block.isHide)" @update:model-value="visible"><el-option label="显示" :value="true" /><el-option label="隐藏并保留配置" :value="false" /></el-select></el-form-item>
            <DiyNewsAuthorFields v-if="kind==='news'" :block="block" :disabled="!canEdit" @change="setLeaf">
              <template #image="slot"><SeckillActivityImagePicker :disabled="!canChooseMedia || slot.disabled" :editor-key="mediaSession(['imgConfig','url']).key" title="选择公告标题图片" @choose="mediaSession(['imgConfig','url']).choose" /><el-button :disabled="!canEdit" @click="setImage(['imgConfig','url'],'')">清空公告标题图片</el-button></template>
