            </DiyNewsAuthorFields>
            <template v-else-if="kind==='hotspot'">
              <h4>热区背景与区域</h4><p class="hint stored">{{text(read(block,['picStyle','url']))||'未选择背景'}}</p>
              <SeckillActivityImagePicker :disabled="!canChooseMedia" :editor-key="mediaSession(['picStyle','url']).key" title="选择热区背景图片" @choose="mediaSession(['picStyle','url']).choose" /><el-button :disabled="!canEdit" @click="setImage(['picStyle','url'],'')">清空热区背景</el-button>
              <p class="hint">更换为不同图片会清空旧区域；续签同一图片保留区域。</p>
              <DiyHotspotAuthorCanvas :image="previewImage(['picStyle','url'])" :image-identity="imageIdentity(read(block,['picStyle','url']))" :areas="items" :editor-key="canvasSession.key" :disabled="!canEdit" :allowed="canvasSession.allowed" @create="canvasSession.create" @rect="canvasSession.rect" @select="itemIndex=$event" />
              <el-alert v-if="listError" :title="listError" type="warning" :closable="false" />
              <div v-for="(raw,index) in items" :key="index" class="item" :data-area-index="index"><h4>热区 {{index+1}}</h4><template v-if="record(raw)"><div class="fields"><el-form-item v-for="(label,key) in coordinateLabels" :key="key" :label="`热区 ${index+1} ${label}`"><el-input-number :model-value="coordinate(raw,key)" :min="0" :max="Math.max(1000000,coordinate(raw,key))" @update:model-value="setCoordinate(index,key,$event)" /></el-form-item></div><el-form-item :label="`热区 ${index+1} 链接`"><el-input :model-value="text(record(raw)?.link)" :maxlength="Math.max(200,text(record(raw)?.link).length)" @update:model-value="setLink(['picStyle','list',index,'link'],$event,200)" /><DiyAuthorLinkPicker :editor-key="linkSession(['picStyle','list',index,'link']).key" :disabled="!canEdit" @choose="linkSession(['picStyle','list',index,'link']).choose" /></el-form-item></template><p v-else class="hint">导入区域结构异常，保留原值；请在 JSON 中修复或明确删除。</p><el-button :disabled="!canEdit" @click="removeItem(index)">删除热区 {{index+1}}</el-button></div>
            </template>
