              <el-alert v-if="listError" :title="listError" type="warning" :closable="false" /><p class="hint">新增最多 4 个版块。导入的额外版块完整保留，用户端展示前 4 个；只有前 4 个图片槽可选择素材。</p>
              <article v-for="(raw,index) in items" :key="index" class="item"><h4>活动版块 {{index+1}}</h4><template v-if="record(raw)"><template v-if="index<4"><img v-if="previewImage(['menuConfig','list',index,'img'])" :src="previewImage(['menuConfig','list',index,'img'])" class="thumb" alt="活动版块图片" /><p class="stored hint">{{text(record(raw)?.img)||'未选择图片'}}</p><SeckillActivityImagePicker :disabled="!canChooseMedia" :editor-key="mediaSession(['menuConfig','list',index,'img']).key" :title="`选择活动版块 ${index+1} 图片`" @choose="mediaSession(['menuConfig','list',index,'img']).choose" /><el-button :disabled="!canEdit" @click="setImage(['menuConfig','list',index,'img'],'')">清空版块图片</el-button></template><el-form-item v-for="(label,field) in ['标题','简介','链接']" :key="field" :label="`活动版块 ${index+1} ${label}`"><el-input :model-value="text(read(raw,['info',field,'value']))" :maxlength="maxLength(['menuConfig','list',index,'info',field,'value'],[4,20,100][field]!)" @update:model-value="field===2?setLink(['menuConfig','list',index,'info',field,'value'],$event,100):setText(['menuConfig','list',index,'info',field,'value'],$event,[4,20][field]!)" /><DiyAuthorLinkPicker v-if="field===2" :editor-key="linkSession(['menuConfig','list',index,'info',2,'value']).key" :disabled="!canEdit" @choose="linkSession(['menuConfig','list',index,'info',2,'value']).choose" /></el-form-item></template><p v-else class="hint">导入版块结构异常，保留原值；请在 JSON 中修复或明确删除。</p><div class="toolbar"><el-button :disabled="!canEdit || index===0" @click="moveItem(index,-1)">上移版块</el-button><el-button :disabled="!canEdit || index===items.length-1" @click="moveItem(index,1)">下移版块</el-button><el-button :disabled="!canEdit" @click="removeItem(index)">删除版块 {{index+1}}</el-button></div></article>
              <el-button :disabled="!canEdit || !!listError || items.length>=4" @click="addPartyItem">添加活动版块</el-button>
            </template>
            <h4>通用样式</h4><div class="fields"><el-form-item v-for="field in colours" :key="`${field.key}:${field.index}`" :label="`${labels[kind]}${field.label}`"><el-color-picker :model-value="colour(field)" show-alpha @update:model-value="setColour(field,$event)" /><el-input :model-value="colour(field)" :aria-label="`${labels[kind]}${field.label}`" @update:model-value="setColour(field,$event)" /></el-form-item></div>
            <div class="fields"><el-form-item v-for="key in lengthKeys" :key="key" :label="`${labels[kind]}${lengthLabels[key]}`"><el-input-number :model-value="number(read(block,[key,'val']))" :min="0" :max="Math.max(100,number(read(block,[key,'val'])))" @update:model-value="setLength([key,'val'],$event)" /></el-form-item></div>
            <template v-if="kind!=='activeParty'"><h4>背景圆角</h4><el-select :model-value="flag(read(block,['fillet','type']))?1:0" aria-label="内容组件圆角模式" @update:model-value="radiusType"><el-option label="全部圆角" :value="0" /><el-option label="独立四角" :value="1" /></el-select><el-form-item v-if="!flag(read(block,['fillet','type']))" label="全部圆角值"><el-input-number :model-value="number(read(block,['fillet','val']))" :min="0" :max="Math.max(100,number(read(block,['fillet','val'])))" @update:model-value="setLength(['fillet','val'],$event)" /></el-form-item><div v-else class="fields"><el-form-item v-for="(label,index) in ['左上','右上','左下','右下']" :key="index" :label="`${label}圆角`"><el-input-number :model-value="number(read(block,['fillet','valList',index,'val']))" :min="0" :max="Math.max(100,number(read(block,['fillet','valList',index,'val'])))" @update:model-value="setLength(['fillet','valList',index,'val'],$event)" /></el-form-item></div></template>
          </el-form>
          <el-alert v-if="error" :title="error" type="error" :closable="false" />
          <div class="toolbar"><el-button :disabled="!canEdit || !pageId || !pagePublished || mediaLoading" :loading="mediaLoading" @click="loadSavedMedia">读取已发布内容图片预览</el-button></div>
          <DiyEditorialPreview v-if="kind!=='hotspot'" :block="previewBlock" />
        </template>
      </template>
      <p v-else class="hint">此页面暂无新闻、热区或活动组件。</p>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { useAuthStore } from '@/stores/auth';
import { getToken } from '@/utils/auth';
import SeckillActivityImagePicker from '@/pages/activity/SeckillActivityImagePicker.vue';
import DiyAuthorLinkPicker from './DiyAuthorLinkPicker.vue';
import DiyNewsAuthorFields from './DiyNewsAuthorFields.vue';
import DiyHotspotAuthorCanvas from './DiyHotspotAuthorCanvas.vue';
import DiyEditorialPreview from './DiyEditorialPreview.vue';
import { EDITORIAL_NAMES as names, editorialLabels as labels, editorialKind, editorialEntries, editorialDocument, editorialRecord as record, editorialRead as read, addEditorialBlock, moveEditorialBlock, editorialImageIdentity as imageIdentity, editorialMediaPaths, canonicalEditorialBlock, editorialPreviewUrl, editorialList, type EditorialKind, type EditorialPath, type EditorialRecord, type EditorialRect } from '@/utils/diyEditorialEditor';
import { projectNewsAuthorFields, newsAuthorPatch } from '@/utils/diyNewsAuthorFields';
import { DIY_EDITORIAL_DEFAULTS } from '@/utils/diyEditorialDefaults';
import { navFlag as flag, navText as text, navSet, navigationLink } from '@/utils/diyNavigationEditor';
import { stateNumber as number } from '@/utils/diyStateEditor';
import { safeDiyColor } from '@/utils/diyStateProjection';
const props=withDefaults(defineProps<{modelValue:string;editorKey:string;disabled?:boolean;pageId?:number;pagePublished?:boolean}>(),{disabled:false,pageId:0,pagePublished:false}),emit=defineEmits<{'update:modelValue':[value:string]}>(),auth=useAuthStore();
const selected=ref(-1),itemIndex=ref(-1),addKind=ref<EditorialKind>('news'),revision=ref(0),error=ref(''),previews=ref<Record<string,string>>({}),mediaLoading=ref(false),leaseTick=ref(0);
let alive=true,lastCommitted='',mediaAbort:AbortController|null=null,leaseTimer:ReturnType<typeof setTimeout>|undefined;
type OwnEcho={beforeRaw:string;expectedRaw:string;owner:string;editor:string;index:number;disabled:boolean;pageId:number;pagePublished:boolean;leases:Record<string,string>;echo:boolean};
let pendingOwnEcho:OwnEcho|null=null;
function ownEchoCurrent(own:OwnEcho){return editable()&&own.owner===actor()&&own.editor===props.editorKey&&own.index===selected.value&&own.disabled===props.disabled&&own.pageId===props.pageId&&own.pagePublished===props.pagePublished&&own.expectedRaw===props.modelValue;}
const actor=()=>`${auth.token}:${auth.userInfo?.id}:${auth.userInfo?.level}:${auth.uniqueAuth.join(',')}:${getToken()}:${localStorage.getItem('admin_session')}`;
function editable(){return alive&&!props.disabled&&!!auth.token&&auth.token===getToken()&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('dise.manage'));}
const canEdit=computed(()=>{void revision.value;return editable();}),canChooseMedia=computed(()=>canEdit.value&&!!auth.userInfo&&(auth.userInfo.level===0||auth.uniqueAuth.includes('attachment.view')));
const parsed=computed(()=>{try{return{value:editorialDocument(props.modelValue),error:''};}catch(reason){return{value:null,error:reason instanceof Error?reason.message:'装修 JSON 无效'};}}),document=computed(()=>parsed.value.value),entries=computed(()=>editorialEntries(document.value??[])),block=computed(()=>record(document.value?.[selected.value])),kind=computed(()=>editorialKind(block.value?.name));
const listPath=computed<EditorialPath>(()=>kind.value==='hotspot'?['picStyle','list']:['menuConfig','list']),listResult=computed(()=>{try{return{value:block.value&&kind.value!=='news'?editorialList(block.value,listPath.value):[],error:''};}catch(reason){return{value:[],error:reason instanceof Error?reason.message:'列表异常'};}}),items=computed(()=>listResult.value.value),listError=computed(()=>listResult.value.error);
const lengthLabels:Record<string,string>={topConfig:'上边距',bottomConfig:'下边距',prConfig:'左右边距',mbConfig:'组件间距'},lengthKeys=computed(()=>kind.value==='activeParty'?['mbConfig']:['topConfig','bottomConfig','prConfig','mbConfig']);
type Colour={key:string;index:number;label:string;fallback:string};
const colours=computed<Colour[]>(()=>!kind.value?[]:Object.entries(DIY_EDITORIAL_DEFAULTS[kind.value]).flatMap(([key,raw])=>{const field=record(raw);if(!Array.isArray(field?.color))return[];if(kind.value==='news'){const news=projectNewsAuthorFields(block.value??{});if(key==='titleBgColor'&&!news.showTitleBackground||key==='titleColor'&&!news.showTitleColor||key==='bntColor'&&!news.showButtonColor)return[];}return field.color.map((raw,index)=>({key,index,label:`${String(field.title??key)}${field.color instanceof Array&&field.color.length>1?index===0?'起始色':'结束色':''}`,fallback:String(record(raw)?.item??'#ffffff')}));}));
const coordinateLabels={starX:'左侧坐标',starY:'顶部坐标',areaWidth:'宽度',areaHeight:'高度'};
function stamp(){return{revision:revision.value,actor:actor(),editor:props.editorKey,index:selected.value,raw:props.modelValue};}
function current(s:ReturnType<typeof stamp>){return editable()&&s.revision===revision.value&&s.actor===actor()&&s.editor===props.editorKey&&s.index===selected.value&&s.raw===props.modelValue;}
function invalidate(preserveOwnEcho:unknown=false){if(preserveOwnEcho!==true)pendingOwnEcho=null;revision.value++;error.value='';mediaAbort?.abort();mediaAbort=null;mediaLoading.value=false;previews.value={};clearTimeout(leaseTimer);leaseTimer=undefined;leaseTick.value++;}
watch(entries,()=>{if(!entries.value.some(row=>row.index===selected.value))selected.value=entries.value[0]?.index??-1;},{immediate:true});
watch(selected,()=>invalidate(),{flush:'sync'});
watch(()=>[props.modelValue,props.editorKey,props.disabled,props.pageId,props.pagePublished,actor()],(next,previous)=>{
  const own=pendingOwnEcho,echo=!!own&&!own.echo&&!!previous&&previous[0]===own.beforeRaw&&next[0]===own.expectedRaw&&next.slice(1).every((value,index)=>value===previous[index+1])&&ownEchoCurrent(own);
  invalidate(echo);if(echo&&own)own.echo=true;
},{flush:'sync'});
window.addEventListener('admin-session-changed',invalidate);window.addEventListener('admin-auth-expired',invalidate);window.addEventListener('storage',invalidate);
onBeforeUnmount(()=>{alive=false;invalidate();window.removeEventListener('admin-session-changed',invalidate);window.removeEventListener('admin-auth-expired',invalidate);window.removeEventListener('storage',invalidate);});
function commit(value:unknown[]){if(!editable())return false;try{
  const raw=JSON.stringify(value,null,2);editorialDocument(raw);
  const own:OwnEcho={beforeRaw:props.modelValue,expectedRaw:raw,owner:actor(),editor:props.editorKey,index:selected.value,disabled:props.disabled,pageId:props.pageId,pagePublished:props.pagePublished,leases:{...previews.value},echo:false};
  invalidate();pendingOwnEcho=own;lastCommitted=raw;emit('update:modelValue',raw);
  void nextTick(()=>{
    if(pendingOwnEcho!==own)return;
    if(!own.echo||!ownEchoCurrent(own)){pendingOwnEcho=null;return;}
    const next:Record<string,string>={};
    if(block.value)for(const path of editorialMediaPaths(block.value)){const raw=read(block.value,path),identity=imageIdentity(raw),lease=own.leases[identity];if(lease&&editorialPreviewUrl(raw,lease))next[identity]=lease;}
    renewLeases(next);
  });return true;
}catch(reason){error.value=reason instanceof Error?reason.message:'无法完整保存';return false;}}
function edit(change:(row:EditorialRecord)=>boolean|void){if(!editable()||!document.value||!block.value||!kind.value)return false;try{const value=structuredClone(document.value),row=record(value[selected.value]);if(!row||change(row)===false)return false;return commit(value);}catch(reason){error.value=reason instanceof Error?reason.message:'当前字段无法修改';return false;}}
function setLeaf(path:EditorialPath,value:unknown){if(read(block.value,path)===value)return false;return edit(row=>navSet(row,path,value));}
function select(value:unknown){if(typeof value==='number'&&entries.value.some(entry=>entry.index===value)){invalidate();selected.value=value;itemIndex.value=-1;}}
function add(duplicate=false){if(!editable()||!document.value)return;try{const k=duplicate?kind.value:addKind.value;if(!k)return;const result=addEditorialBlock(document.value,k,duplicate&&block.value?block.value:undefined);if(commit(result.value))selected.value=result.selected;}catch(reason){error.value=reason instanceof Error?reason.message:'无法添加组件';}}
function remove(){if(!document.value||!kind.value)return;const value=structuredClone(document.value);value.splice(selected.value,1);if(commit(value))selected.value=-1;}
function move(direction:-1|1){if(!document.value)return;try{const result=moveEditorialBlock(document.value,selected.value,direction);if(commit(result.value))selected.value=result.selected;}catch(reason){error.value=reason instanceof Error?reason.message:'不能移动组件';}}
function visible(value:unknown){if(typeof value==='boolean'&&flag(block.value?.isHide)!==!value)setLeaf(['isHide'],!value);}
function maxLength(path:EditorialPath,max:number){return Math.max(max,text(read(block.value,path)).length);}
function setText(path:EditorialPath,value:unknown,max:number){if(typeof value==='string'&&!/[\u0000-\u001f\u007f]/u.test(value)&&value.length<=maxLength(path,max))setLeaf(path,value);}
function setLink(path:EditorialPath,value:unknown,max=200){if(typeof value!=='string'||value.length>maxLength(path,max))return;try{const safe=navigationLink(value);if(kind.value==='news'){const patch=newsAuthorPatch(block.value!,path,safe);if(patch)setLeaf(patch.path,patch.value);}else setLeaf(path,safe);}catch(reason){error.value=reason instanceof Error?reason.message:'链接无效';}}
function linkSession(path:EditorialPath){const issued=stamp(),key=`${props.editorKey}:${revision.value}:${selected.value}:${JSON.stringify(path)}`;return{key,choose:(target:{url:string})=>{if(current(issued))setLink(path,target.url,kind.value==='activeParty'?100:200);}};}
function setLength(path:EditorialPath,value:unknown){if(typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=100&&value!==number(read(block.value,path)))setLeaf(path,value);}
function radiusType(value:unknown){if((value===0||value===1)&&flag(read(block.value,['fillet','type']))!==(value===1))setLeaf(['fillet','type'],value);}
function colour(field:Colour){return safeDiyColor(read(block.value,[field.key,'color',field.index,'item']),field.fallback);}
function setColour(field:Colour,value:unknown){if(typeof value==='string'&&safeDiyColor(value,'')===value.trim())setLeaf([field.key,'color',field.index,'item'],value.trim());}
function removeItem(index:number){if(listError.value||!Number.isInteger(index)||index<0||index>=items.value.length)return;const list=structuredClone(items.value);list.splice(index,1);setLeaf(listPath.value,list);}
function moveItem(index:number,direction:-1|1){if(listError.value||index<0||index>=items.value.length||index+direction<0||index+direction>=items.value.length)return;const list=structuredClone(items.value);[list[index],list[index+direction]]=[list[index+direction],list[index]];setLeaf(listPath.value,list);}
function addPartyItem(){if(kind.value!=='activeParty'||listError.value||items.value.length>=4)return;const template=record(items.value.at(-1))??DIY_EDITORIAL_DEFAULTS.activeParty.menuConfig.list[0];setLeaf(listPath.value,[...structuredClone(items.value),structuredClone(template)]);}
function coordinate(raw:unknown,key:keyof typeof coordinateLabels){return number(record(raw)?.[key]);}
function setCoordinate(index:number,key:keyof typeof coordinateLabels,value:unknown){if(typeof value==='number'&&Number.isFinite(value)&&value>=0&&value<=1e6&&value!==coordinate(items.value[index],key))setLeaf(['picStyle','list',index,key],value);}
function mediaPathAllowed(path:EditorialPath){return !!block.value&&editorialMediaPaths(block.value).some(p=>JSON.stringify(p)===JSON.stringify(path));}
function setImage(path:EditorialPath,value:string){if(!mediaPathAllowed(path))return false;const canonical=imageIdentity(value);if(canonical&&!(canonical.startsWith('https://')||/^\/(?!\/)/u.test(canonical))||/[\u0000-\u0020\u007f\\]/u.test(canonical))return false;if(imageIdentity(read(block.value,path))===canonical)return false;return edit(row=>{navSet(row,path,canonical);if(row.name==='hotspot'&&canonical)navSet(row,['picStyle','list'],[]);});}
function previewImage(path:EditorialPath){void leaseTick.value;if(!editable()||!block.value||!mediaPathAllowed(path))return '';const raw=read(block.value,path);return editorialPreviewUrl(raw,previews.value[imageIdentity(raw)]);}
function renewLeases(next:Record<string,string>){previews.value=next;clearTimeout(leaseTimer);leaseTick.value++;const expires=Object.values(next).flatMap(url=>{const match=/[?&]expires=(\d+)/u.exec(url);return match?[Number(match[1])*1000]:[];});if(expires.length)leaseTimer=setTimeout(()=>{const retained=Object.fromEntries(Object.entries(previews.value).filter(([,url])=>!!editorialPreviewUrl(url,url)));renewLeases(retained);},Math.min(2147483647,Math.max(1,Math.min(...expires)-Date.now()+1)));}
function mediaSession(path:EditorialPath){const issued=stamp(),owner=actor(),editor=props.editorKey,index=selected.value;return{key:`${props.editorKey}:${revision.value}:${index}:${JSON.stringify(path)}`,choose:async(reference:string,signed:string)=>{if(!current(issued)||!canChooseMedia.value||!mediaPathAllowed(path))return;const approved=editorialPreviewUrl(reference,signed);if(!approved)return;const canonical=imageIdentity(reference);if(imageIdentity(read(block.value,path))===canonical){renewLeases({...previews.value,[canonical]:approved});return;}if(!setImage(path,reference))return;const expected=lastCommitted,own=pendingOwnEcho;await nextTick();if(own&&pendingOwnEcho===own&&own.echo&&ownEchoCurrent(own)&&alive&&editable()&&canChooseMedia.value&&actor()===owner&&props.editorKey===editor&&selected.value===index&&props.modelValue===expected&&mediaPathAllowed(path)&&imageIdentity(read(block.value,path))===canonical&&editorialPreviewUrl(reference,approved))renewLeases({...previews.value,[canonical]:approved});}};}
