async function loadSavedMedia(){if(!editable()||!block.value||!props.pageId||!props.pagePublished)return;mediaAbort?.abort();const issued=stamp(),id=props.pageId,expected=JSON.stringify(canonicalEditorialBlock(block.value,true)),paths=editorialMediaPaths(block.value),controller=new AbortController();mediaAbort=controller;mediaLoading.value=true;renewLeases({});error.value='';try{const response=await fetch(`/api/diy/get_diy/${id}`,{method:'GET',credentials:'omit',cache:'no-store',signal:controller.signal}),body=record(await response.json()),data=record(body?.data);if(!current(issued)||props.pageId!==id||!props.pagePublished||controller.signal.aborted)return;if(!response.ok||body?.status!==200||!Array.isArray(data?.value))throw Error('公开组件图片暂不可用');const found=data.value.map(record).find(row=>row&&JSON.stringify(canonicalEditorialBlock(row,true))===expected);if(!found)throw Error('当前组件与已发布内容不同，请保存后再读取');const next:Record<string,string>={};for(const path of paths){const raw=read(block.value,path),approved=editorialPreviewUrl(raw,read(found,path));if(approved)next[imageIdentity(raw)]=approved;}renewLeases(next);}catch(reason){if(current(issued)&&mediaAbort===controller&&!controller.signal.aborted)error.value=reason instanceof Error?reason.message:'组件图片预览失败';}finally{if(mediaAbort===controller){mediaAbort=null;mediaLoading.value=false;}}}
